import{_ as e,o as t,c as i,a2 as l}from"./chunks/framework.Boholvbs.js";const u=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quickstart.md","filePath":"guide/quickstart.md","lastUpdated":1791785647000}'),r={name:"guide/quickstart.md"};function o(s,a,c,n,d,h){return t(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>四步接入：注册 → 开通订阅 → 创建密钥 → 配置客户端。</p><p>控制台地址：<a href="https://relay.panghuli.tech" target="_blank" rel="noreferrer">https://relay.panghuli.tech</a></p><h2 id="_1-注册" tabindex="-1">1. 注册 <a class="header-anchor" href="#_1-注册" aria-label="Permalink to &quot;1. 注册&quot;">​</a></h2><p>打开控制台，点「注册」。注册需要<strong>邀请码</strong>，没有的话先<a href="./contact">联系我们</a>。</p><h2 id="_2-开通订阅" tabindex="-1">2. 开通订阅 <a class="header-anchor" href="#_2-开通订阅" aria-label="Permalink to &quot;2. 开通订阅&quot;">​</a></h2><p>在左侧菜单进入「购买订阅」，选一个套餐，在收银台付款。 也可以在「兑换」页输入订阅兑换码开通。</p><p>开通后在「我的订阅」能看到套餐、有效期和本周已用额度。</p><p>套餐怎么选，见<a href="./billing">订阅与余额</a>。</p><h2 id="_3-创建-api-密钥" tabindex="-1">3. 创建 API 密钥 <a class="header-anchor" href="#_3-创建-api-密钥" aria-label="Permalink to &quot;3. 创建 API 密钥&quot;">​</a></h2><p>进入「API 密钥」→「创建密钥」，<strong>分组选你订阅的那一档</strong>（例如 Claude Max20x）。</p><div class="tip custom-block"><p class="custom-block-title">分组列表里没有我买的那档？</p><p>订阅类分组只有在订阅生效后才出现在可选列表里。先确认「我的订阅」里有这一档且未过期。</p></div><div class="warning custom-block"><p class="custom-block-title">保管好密钥</p><p>密钥等同于你的账号额度，不要发到群里、不要提交到代码仓库。泄露了就在「API 密钥」里删掉重建。</p></div><h2 id="_4-配置客户端" tabindex="-1">4. 配置客户端 <a class="header-anchor" href="#_4-配置客户端" aria-label="Permalink to &quot;4. 配置客户端&quot;">​</a></h2><p>在「API 密钥」列表里，每个密钥后面有两个按钮：</p><ul><li><strong>使用密钥</strong>：按你的系统（macOS / Linux / Windows）生成 Claude Code、Codex CLI 的配置，复制即可</li><li><strong>导入到 CCS</strong>：已安装 <a href="./../clients/cc-switch">CC Switch</a> 的话，一键导入</li></ul><p>分客户端的详细说明：</p><ul><li><a href="./../clients/claude-code">Claude Code</a></li><li><a href="./../clients/codex">Codex CLI</a></li><li><a href="./../clients/cc-switch">CC Switch 一键导入</a></li></ul><h2 id="_5-查看用量" tabindex="-1">5. 查看用量 <a class="header-anchor" href="#_5-查看用量" aria-label="Permalink to &quot;5. 查看用量&quot;">​</a></h2><ul><li>「我的订阅」：本周、今日已用额度和剩余额度</li><li>「使用记录」：每一次请求的模型、token 数和折算费用</li></ul>',20)])])}const _=e(r,[["render",o]]);export{u as __pageData,_ as default};
